package com.lmspilot.learning.api;
import com.fasterxml.jackson.databind.ObjectMapper;import com.lmspilot.learning.domain.*;import com.lmspilot.support.security.CurrentUser;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.time.*;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;
record XapiStatementRequest(@NotBlank String verb,@NotNull UUID objectId,@NotNull XapiObjectType objectType,UUID courseId,Map<String,Object> result,Map<String,Object> context,Instant occurredAt){} record XapiStatementResponse(UUID id,UUID actorUserId,String verb,UUID objectId,XapiObjectType objectType,UUID courseId,Map<String,Object> result,Map<String,Object> context,Instant occurredAt,Instant storedAt){}
@Service @Transactional class XapiService{private final XapiStatementRepository repo;private final ObjectMapper mapper;XapiService(XapiStatementRepository r,ObjectMapper m){repo=r;mapper=m;}XapiStatementResponse record(XapiStatementRequest i){XapiStatementEntity e=new XapiStatementEntity();e.actorUserId=user();e.verb=i.verb().trim();e.objectId=i.objectId();e.objectType=i.objectType();e.courseId=i.courseId();e.occurredAt=i.occurredAt()==null?Instant.now():i.occurredAt();try{e.resultJson=mapper.writeValueAsString(i.result()==null?Map.of():i.result());e.contextJson=mapper.writeValueAsString(i.context()==null?Map.of():i.context());}catch(Exception ignored){}return view(repo.save(e));}List<XapiStatementResponse> mine(){return byUser(user());}List<XapiStatementResponse> byUser(UUID u){return repo.findTop200ByActorUserIdOrderByOccurredAtDesc(u).stream().map(this::view).toList();}List<XapiStatementResponse> byCourse(UUID c){return repo.findTop500ByCourseIdOrderByOccurredAtDesc(c).stream().map(this::view).toList();}private XapiStatementResponse view(XapiStatementEntity e){return new XapiStatementResponse(e.id,e.actorUserId,e.verb,e.objectId,e.objectType,e.courseId,read(e.resultJson),read(e.contextJson),e.occurredAt,e.storedAt);}private Map<String,Object> read(String s){try{return s==null?Map.of():mapper.readValue(s,Map.class);}catch(Exception e){return Map.of();}}private UUID user(){try{return CurrentUser.id();}catch(Exception e){return new UUID(0,1);}}}
@RestController @RequestMapping("/api/v1/xapi/statements") public class XapiApi{private final XapiService service;public XapiApi(XapiService s){service=s;}@PostMapping public XapiStatementResponse record(@Valid @RequestBody XapiStatementRequest i){return service.record(i);}@GetMapping("/me") public List<XapiStatementResponse> mine(){return service.mine();}@GetMapping("/users/{userId}") public List<XapiStatementResponse> byUser(@PathVariable UUID userId){return service.byUser(userId);}@GetMapping public List<XapiStatementResponse> byCourse(@RequestParam UUID courseId){return service.byCourse(courseId);} }
